import heapq
from typing import Dict, List, Tuple


def shortest_path(graph: dict[str, dict[str, float]], start: str, goal: str) -> tuple[float, list[str]]:
    if start == goal:
        return (0, [start])

    # Check if start or goal are unknown nodes
    # A node is "known" if it appears as a key in graph or as a value in any graph[u]
    # But the problem says "If goal is unreachable (or a node is unknown) return (inf, [])"
    # Let's interpret "unknown" as: if start is not in graph and start != goal, or if goal is not reachable.
    # Actually, let's just run Dijkstra and if goal is not reached, return inf.

    # Initialize distances
    dist = {start: 0.0}
    prev = {}
    visited = set()

    # Priority queue: (distance, node)
    pq = [(0.0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)

        if u == goal:
            break

        # Explore neighbors
        if u in graph:
            for v, w in graph[u].items():
                if v in visited:
                    continue
                new_dist = d + w
                if v not in dist or new_dist < dist[v]:
                    dist[v] = new_dist
                    prev[v] = u
                    heapq.heappush(pq, (new_dist, v))

    if goal not in dist:
        return (float("inf"), [])

    # Reconstruct path
    path = []
    node = goal
    while node != start:
        path.append(node)
        node = prev[node]
    path.append(start)
    path.reverse()

    return (dist[goal], path)
